const PAYMENT_METHODS: PaymentMethod[] = ['efectivo', 'tarjeta'];
const CASHIERS: string[] = ['Turno Mañana', 'Turno Tarde'];

export const INITIAL_SALES: Sale[] = RAW_TICKETS_COMPACT.slice().reverse().map((t) => {
  const [folio, dateStr, payIdx, shiftIdx, rawItems] = t;
  let total = 0;
  const items = rawItems.map((pair, idx) => {
    const [pIdx, qty] = pair;
    const product = INITIAL_PRODUCTS[pIdx] || INITIAL_PRODUCTS[0];
    const lineTotal = qty * product.salePrice;
    total += lineTotal;
    return {
      id: `ci-${folio}-${idx}`,
      product,
      quantity: qty,
      unitPrice: product.salePrice,
      total: lineTotal
    };
  });
  const paymentMethod = PAYMENT_METHODS[payIdx] || 'efectivo';
  const amountPaid = paymentMethod === 'efectivo' ? Math.ceil(total / 50) * 50 : total;
  return {
    id: `sale-${folio}`,
    folio,
    date: dateStr,
    items,
    subtotal: total,
    discount: 0,
    total,
    paymentMethod,
    amountPaid,
    change: amountPaid - total,
    cashier: CASHIERS[shiftIdx] || 'Turno Mañana',
    syncedToSheets: true
  };
});

